const productCopy={zh:{tag:'ORBI FOR MAC',title:'小小刘海。<br><span>大有可为。</span>',intro:'音乐、日程、剪贴板。把常用的事，放在 Mac 顶部。<br>轻轻移入，即刻展开。',try:'亲手试试',download:'了解下载',demo:'交互演示 · 根据当前应用界面重现，内容为示例',hint:'将鼠标移入顶部刘海，或点击展开',expand:'展开 Orbi 演示',collapse:'收起 Orbi 演示',music:'音乐',calendar:'日历',clipboard:'剪贴板',date:'9月28日 星期一',meeting:'设计讨论',work:'工作',time:'15 分钟后',sample:'让好想法，继续流动。',note:'下一步：完善产品细节',play:'播放示例动画',pause:'暂停示例动画',prev:'上一首示例',next:'下一首示例',flowTag:'RIGHT WHERE YOU NEED IT',flowTitle:'需要时，展开。<br><span>专注时，隐去。</span>',flowIntro:'不必挪开当前窗口。音乐响起时，顶部呈现播放状态与律动；鼠标移入，三个模块一起出现。',flowSteps:['安静待命','音乐正在播放','工作台已展开'],featuresTitle:'三件日常小事。<br><span>一次轻松触达。</span>',musicTitle:'下一首，不必切走。',musicBody:'查看 Apple Music 的歌曲与艺人，直接暂停、播放或切歌。其他正在发声的应用，也能显示应用名称和音频律动。',calendarTitle:'下一程，抬眼就知道。',calendarBody:'显示今天的日期、正在进行或即将开始的日程，以及距离开始的时间。让接下来的安排，始终心中有数。',clipTitle:'刚才复制的，还在。',clipBody:'保留最近 15 条文字记录。点选即可重新复制，也可以一键清空历史，让想法在任务之间顺畅接续。',clipHint:'点击示例文字，体验选择反馈',selected:'已选中示例',settingsTag:'MAKE ROOM FOR YOURSELF',settingsTitle:'留下你需要的。<br><span>就刚刚好。</span>',settingsBody:'音乐、日历、剪贴板，按需显示。支持开机启动，以及中文、英文和跟随系统的语言设置。',settingsHint:'试着开关模块，看看工作台的变化。',empty:'未启用任何模块',end:'让 Mac 顶部，<br>多一点可能。',endBody:'认识 Orbi 的安装与首次使用。',source:'网页演示不会读取你的音乐、日历或剪贴板。',count:'最近 15 条',soon:'即将开始'},en:{tag:'ORBI FOR MAC',title:'A little notch.<br><span>A lot more possibility.</span>',intro:'Music, calendar, and clipboard. Right at the top of your Mac.<br>Move in. Open up.',try:'Try it yourself',download:'Explore downloads',demo:'Interactive recreation of the current app · Sample content',hint:'Hover over the notch, or click to expand',expand:'Expand the Orbi demo',collapse:'Collapse the Orbi demo',music:'Music',calendar:'Calendar',clipboard:'Clipboard',date:'Mon · Sep 28',meeting:'Design catch-up',work:'Work',time:'In 15 min',sample:'Keep good ideas moving.',note:'Next: refine the product details',play:'Play sample animation',pause:'Pause sample animation',prev:'Previous sample track',next:'Next sample track',flowTag:'RIGHT WHERE YOU NEED IT',flowTitle:'There when you need it.<br><span>Quiet when you don’t.</span>',flowIntro:'Keep your current window in focus. Audio brings playback status and a waveform to the notch. Hover to reveal your workspace.',flowSteps:['Quietly waiting','Music is playing','Your workspace, open'],featuresTitle:'Three everyday essentials.<br><span>One easy reach.</span>',musicTitle:'Next track. Same focus.',musicBody:'See the track and artist in Apple Music. Pause, play, or skip without switching windows. Other audio apps show their name and a live waveform.',calendarTitle:'Your next moment, at a glance.',calendarBody:'See today’s date, your current or next event, and the time until it starts. Stay aware of what’s coming next.',clipTitle:'Copied. Still within reach.',clipBody:'Keep your 15 most recent text entries. Select one to copy it again, or clear your history in one step. Keep ideas moving between tasks.',clipHint:'Select sample text to preview the feedback',selected:'Sample selected',settingsTag:'MAKE ROOM FOR YOURSELF',settingsTitle:'Just what you need.<br><span>Just right.</span>',settingsBody:'Show music, calendar, and clipboard as you need them. With launch at login and English, Chinese, or system language settings.',settingsHint:'Toggle a module to see your workspace change.',empty:'No modules enabled',end:'A little more possibility.<br>At the top of your Mac.',endBody:'Explore installation and your first steps with Orbi.',source:'This demo does not access your music, calendar, or clipboard.',count:'15 recent entries',soon:'Up next'}};
function waves(){return '<span class="audio-bars" aria-hidden="true">'+[0,1,2,3,4].map(i=>`<i style="--bar:${i}"></i>`).join('')+'</span>'}
function modules(t,interactive=false){return `<div class="module mod-music"><div class="module-label">♫ &nbsp; ${t.music}</div><div class="music-row"><div class="album" aria-hidden="true">♫</div><div class="track"><strong class="track-name">Quiet Morning</strong><small>Orbi Sessions</small><div class="playback">${interactive?`<button data-track="-1" aria-label="${t.prev}">‹‹</button><button class="play-toggle" aria-label="${t.pause}" aria-pressed="true">Ⅱ</button><button data-track="1" aria-label="${t.next}">››</button>`:'<span>‹‹ &nbsp; Ⅱ &nbsp; ››</span>'}</div></div></div></div><div class="module mod-calendar"><div class="module-label">▦ &nbsp; ${t.calendar}</div><small>${t.date}</small><div class="event"><div><strong>10:30</strong><small>${t.time}</small></div><div><strong>${t.meeting}</strong><small>${t.work}</small></div></div></div><div class="module mod-clipboard"><div class="module-label">▤ &nbsp; ${t.clipboard}<span>2</span></div><div class="clip-line">${t.sample}</div><div class="clip-line muted">${t.note}</div></div>`}
function productPage(t){const p=productCopy[lang];return `<section class="hero product-hero"><img class="app-icon" src="/assets/orbi-icon.png" width="68" height="68" alt="Orbi"><div class="eyebrow">${p.tag}</div><h1>${p.title}</h1><p>${p.intro}</p><div class="actions"><a class="pill" href="#product-demo">${p.try}</a><a class="textlink" href="/download/">${p.download} ↗</a></div><div class="desktop-demo" id="product-demo"><div class="desktop-menubar" aria-hidden="true"><span>Orbi &nbsp; <span class="menu-extra">Finder &nbsp; File &nbsp; Edit</span></span><span>Mon 9:41</span></div><div class="notch-demo is-playing" id="interactive-notch"><button class="notch-trigger" aria-expanded="false" aria-controls="demo-modules" aria-label="${p.expand}"><span>♫</span><span class="notch-center"></span>${waves()}</button><div class="notch-modules" id="demo-modules" inert>${modules(p,true)}</div></div><div class="desktop-brand" aria-hidden="true">orbi<span>${lang==='zh'?'日常，就此顺手。':'Your day. Within reach.'}</span></div><div class="demo-hint">${p.hint}</div></div><p class="caption">${p.demo}</p></section><section class="notch-scroll dark"><div class="scroll-pin"><div class="eyebrow">${p.flowTag}</div><h2>${p.flowTitle}</h2><p>${p.flowIntro}</p><div class="morph-area" aria-hidden="true"><div class="morph-notch"><div class="morph-compact"><span>♫</span>${waves()}</div><div class="morph-modules">${modules(p)}</div></div></div><div class="flow-steps">${p.flowSteps.map((s,i)=>`<span data-step="${i}"><b>0${i+1}</b>${s}</span>`).join('')}</div></div></section><section class="section feature-section"><h2 class="reveal">${p.featuresTitle}</h2><div class="feature-grid"><article class="feature-tile music-tile reveal"><div class="eyebrow">01 / APPLE MUSIC</div><h3>${p.musicTitle}</h3><p>${p.musicBody}</p><div class="feature-player is-playing"><div class="big-note" aria-hidden="true">♫</div><strong>Quiet Morning</strong><small>Orbi Sessions</small><div class="visual-wave">${waves()}</div><div class="sample-badge">${lang==='zh'?'示例曲目':'Sample track'}</div></div></article><article class="feature-tile calendar-tile reveal"><div class="eyebrow">02 / ${p.calendar}</div><h3>${p.calendarTitle}</h3><p>${p.calendarBody}</p><div class="calendar-preview"><small>${p.date}</small><div class="calendar-event"><div class="event-time">10:30<span>${p.time}</span></div><div><strong>${p.meeting}</strong><small>${p.work}</small></div></div><div class="calendar-bottom">${p.soon} <span>→</span></div></div></article><article class="feature-tile clipboard-tile reveal"><div class="feature-copy"><div class="eyebrow">03 / ${p.clipboard}</div><h3>${p.clipTitle}</h3><p>${p.clipBody}</p></div><div class="clipboard-preview"><div class="clip-top">${p.clipboard}<small>${p.count}</small></div>${[p.sample,p.note,'hello@orbi.example'].map(s=>`<button class="sample-clip"><span>${s}</span><span aria-hidden="true">▤</span></button>`).join('')}<div class="clip-feedback" role="status">${p.clipHint}</div></div></article></div></section><section class="settings-section"><div class="section"><div class="section-top"><div><div class="eyebrow">${p.settingsTag}</div><h2>${p.settingsTitle}</h2></div><p>${p.settingsBody}</p></div><div class="custom-workspace"><div class="settings-preview">${modules(p)}<span class="empty-modules" hidden>${p.empty}</span></div><div class="module-toggles">${['music','calendar','clipboard'].map(k=>`<label><input type="checkbox" data-module="${k}" checked><span class="switch-track"></span>${p[k]}</label>`).join('')}</div><p class="small center">${p.settingsHint}</p></div></div></section><section class="section center reveal"><img src="/assets/orbi-icon.png" class="closing-icon" width="86" height="86" alt=""><h2>${p.end}</h2><p>${p.endBody}</p><a class="pill" href="/download/">${p.download} ↗</a><p class="small">${p.source}</p></section>`}
let demoCleanup=()=>{};
function setupProduct(){demoCleanup();if(page!=='product')return;const p=productCopy[lang],notch=document.querySelector('#interactive-notch'),trigger=notch.querySelector('.notch-trigger'),body=notch.querySelector('.notch-modules');let timer,pinned=false;const setOpen=open=>{notch.classList.toggle('expanded',open);trigger.setAttribute('aria-expanded',String(open));trigger.setAttribute('aria-label',open?p.collapse:p.expand);body.inert=!open};notch.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){clearTimeout(timer);setOpen(true)}});notch.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!pinned)timer=setTimeout(()=>setOpen(false),420)});trigger.onclick=()=>{pinned=!pinned;setOpen(pinned)};notch.onkeydown=e=>{if(e.key==='Escape'){pinned=false;setOpen(false);trigger.focus()}};notch.addEventListener('focusout',e=>{if(!notch.contains(e.relatedTarget)&&!pinned)setOpen(false)});let playing=true,track=0;const tracks=['Quiet Morning','Blue Hour','Slow Orbit'];notch.querySelector('.play-toggle').onclick=e=>{playing=!playing;notch.classList.toggle('is-playing',playing);e.currentTarget.textContent=playing?'Ⅱ':'▶';e.currentTarget.setAttribute('aria-label',playing?p.pause:p.play);e.currentTarget.setAttribute('aria-pressed',String(playing))};notch.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{track=(track+Number(b.dataset.track)+tracks.length)%tracks.length;notch.querySelector('.track-name').textContent=tracks[track]});document.querySelectorAll('.sample-clip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sample-clip').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelector('.clip-feedback').textContent=p.selected+' · '+b.firstElementChild.textContent});document.querySelectorAll('[data-module]').forEach(input=>input.onchange=()=>{document.querySelector('.settings-preview .mod-'+input.dataset.module).hidden=!input.checked;document.querySelector('.empty-modules').hidden=!!document.querySelector('[data-module]:checked')});const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const motionObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('animate-wave',e.isIntersecting&&!reduce)));document.querySelectorAll('.notch-demo,.feature-player').forEach(e=>motionObserver.observe(e));demoCleanup=()=>{clearTimeout(timer);motionObserver.disconnect()};updateProductScroll()}
function updateProductScroll(){const section=document.querySelector('.notch-scroll');if(!section)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const rect=section.getBoundingClientRect(),progress=reduced?1:Math.max(0,Math.min(1,-rect.top/Math.max(1,rect.height-innerHeight)));const unfold=Math.max(0,Math.min(1,(progress-.36)/.38));section.style.setProperty('--unfold',unfold);section.style.setProperty('--audio',Math.max(0,Math.min(1,progress/.22)));section.querySelectorAll('[data-step]').forEach((el,i)=>el.classList.toggle('active',i===(progress<.22?0:progress<.62?1:2)))}
